import json
trace=[
{"step":1,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_init)","line":1410,"var":"MBREX(search_re)","code":"if (argc > 1) { MBREX(search_re) = php_mbregex_compile_pattern(arg_pattern, arg_pattern_len, option, MBREX(current_mbctype), syntax); }","note":"The attacker provides the regex that becomes the initial global search pattern."},
{"step":2,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_init)","line":1540,"var":"MBREX(search_str)","code":"ZVAL_STR_COPY(&MBREX(search_str), arg_str);","note":"The attacker-controlled subject string is stored in module-global search state."},
{"step":3,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"_php_mb_regex_ereg_search_exec","line":1458,"var":"MBREX(search_regs)","code":"if (MBREX(search_regs)) { onig_region_free(MBREX(search_regs), 1); } MBREX(search_regs) = onig_region_new();","note":"A search execution frees and reallocates the global match region, creating a narrow temporal window for stale references."},
{"step":4,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"_php_mb_regex_ereg_search_exec","line":1468,"var":"MBREX(search_re)","code":"if (onig_number_of_names(MBREX(search_re)) > 0) { onig_foreach_name(MBREX(search_re), mb_regex_groups_iter, &args); }","note":"The search result processing walks metadata attached to the stored regex object; if that object has been released or replaced, this becomes the UAF read site."},
{"step":5,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"_php_mb_regex_ereg_search_exec","line":1438,"var":"MBREX(search_re)","code":"err = _php_mb_onig_search(MBREX(search_re), str, str + len, str + pos, str + len, MBREX(search_regs), 0);","note":"The actual search call consumes the module-global regex pointer and can trigger the invalid read when the cache/global state is stale."}
]
open('/workspace/candidate_trace.json','w').write(json.dumps(trace,separators=(',',':')))
